import {cards} from './model.js';
export const rewardLabels=['12 · Techcombank Rewards','11 · Points enquiry support','1 · Points not credited due to reversed/cancelled transactions (limit not updated)','Item not supplied'];
export const routes=[
 {path:rewardLabels,systems:cards},
 {path:['01 · Card services','Card security','Lost or stolen card','Permanent card blocking'],systems:[{source:'T24',task:'Identify the card and account'},{source:'Card Management',task:'Check card status and blocking eligibility'},{source:'Case Management',task:'Record the customer request and next steps'}]},
 {path:['02 · Payments & transfers','Transfer enquiry','Beneficiary has not received funds','Interbank transfer tracing'],systems:[{source:'T24',task:'Locate the debit and account'},{source:'Payment Hub',task:'Trace the transfer reference and processing status'},{source:'Case Management',task:'Check prior tracing requests'}]},
 {path:['03 · Digital banking','Access support','Unable to sign in','Device registration assistance'],systems:[{source:'Customer Identity',task:'Verify identity and registered contact details'},{source:'Digital Banking',task:'Review access status and device registration'},{source:'Case Management',task:'Record assisted recovery steps'}]},
 {path:['12 · Techcombank Rewards','11 · Points enquiry support','Points credited incorrectly','Review points calculation'],systems:[{source:'T24',task:'Identify card programme'},{source:'FIMI',task:'Locate qualifying transactions'},{source:'Programme Terms',task:'Check earning rate and exclusions'},{source:'Rewards Portal',task:'Compare credited points and monthly cap'}]}
];
const sampleFindings=[[],[
 ['Card and account matched','Visa Everyday •••• 8824 · Active'],['Card is eligible for blocking','No existing permanent block'],['No duplicate blocking request','Customer confirmation required before any action']
],[['Debit located','VND 2,500,000 · Reference TRF-1027-014'],['Transfer pending reconciliation','Beneficiary receipt not yet confirmed'],['No open tracing case','Prepare a tracing request for operator review']
],[['Registered profile matched','Phone 090 123 4682 · Customer 10002048'],['New device is not registered','Device registration required'],['No open access-support case','Guide customer through approved recovery steps']
],[['Visa Everyday identified','Active card •••• 8824'],['Online purchase located','VND 1,000,000 · 05 Oct 2026'],['Applicable rate confirmed','8% international online rate · Sample programme'],['Credit matches sample calculation','80,000 points credited · Monthly cap not reached']]];
routes.forEach((route,r)=>{if(!r)return;route.systems=route.systems.map((system,i)=>{const [title,body]=sampleFindings[r][i];return {...system,id:`route-${r}-${i}`,title,body,status:'Checked',evidence:{screen:system.source+' · Enquiry',reference:`SM-SAMPLE-${r}-${i+1}`,fields:[['Customer ID','10002048'],['Case type',route.path[3]],['Lookup',system.task],['Record',body]],columns:['Check','Result'],rows:[[system.task,title],['Record details',body]],conclusion:title+'. '+body+'.',note:'Read-only sample lookup. No card, payment or access changes were performed.'}};});});
